        >>> V = zeros((3, 1))
        >>> V
        [0]
        [0]
        [0]
        >>> M.col_insert(1,V)
        [0, 0, 1, 2]
        [1, 0, 2, 3]
        [2, 0, 3, 4]
        """
        if pos is 0:
            return mti.row_join(self)
        assert self.lines == mti.lines
        newmat = self.zeros((self.lines, self.cols + mti.cols))
